/* banco de questões do simulado CNPI-T (carregado só quando você abre o CNPI) */
window.CN_BANCO_DATA={"ct":[{"id":"c0","t":"t1","q":"Qual das premissas abaixo é a base da análise técnica?","o":["O preço desconta tudo, move-se em tendências e a história tende a se repetir","O valor justo da empresa é calculado pelo fluxo de caixa descontado","Os preços seguem um passeio aleatório sem memória","O volume de negócios é irrelevante para a formação de preços"],"c":0,"e":"As três premissas clássicas (Dow, retomadas por Murphy): o mercado desconta tudo, os preços se movem em tendências e a história se repete, porque o comportamento humano se repete.","r":"Murphy, cap. 1"},{"id":"c1","t":"t1","q":"A principal diferença conceitual entre análise técnica e fundamentalista é que a técnica:","o":["Estuda a ação do mercado (preço, volume e contratos em aberto), e a fundamentalista estuda as causas do movimento (oferta, demanda, resultados)","Só pode ser usada em ações, e a fundamentalista só em derivativos","Ignora completamente o tempo, e a fundamentalista só olha o curto prazo","Usa apenas indicadores macroeconômicos"],"c":0,"e":"O técnico estuda o efeito (o movimento de preços); o fundamentalista estuda a causa. Ambos tentam prever a direção dos preços.","r":"Murphy, cap. 1"},{"id":"c2","t":"t1","q":"Num gráfico de barras, a pequena marca horizontal à direita da barra representa:","o":["O preço de fechamento do período","O preço de abertura do período","A máxima do período","O volume negociado"],"c":0,"e":"Na barra OHLC tradicional, o traço à esquerda é a abertura e o traço à direita é o fechamento; o topo e a base da barra são a máxima e a mínima.","r":"Murphy, cap. 3"},{"id":"c3","t":"t1","q":"O gráfico de ponto e figura se diferencia dos demais porque:","o":["Registra apenas variações de preço acima de um tamanho mínimo (box), ignorando o tempo","Mostra abertura, máxima, mínima e fechamento de cada período","Só pode ser usado com dados semanais","Mostra apenas o volume financeiro"],"c":0,"e":"O ponto e figura usa X (altas) e O (baixas) com tamanho de box e critério de reversão; o eixo do tempo não é proporcional.","r":"Murphy, cap. 11; Kirkpatrick"},{"id":"c4","t":"t1","q":"Num gráfico de ponto e figura com box de R$ 1 e reversão de 3 boxes, uma coluna de X só é substituída por uma coluna de O quando o preço:","o":["Cai pelo menos R$ 3 a partir do último X","Cai qualquer valor abaixo do último X","Fecha abaixo da média de 21 períodos","Cai R$ 1 a partir do último X"],"c":0,"e":"A reversão de 3 boxes exige movimento contrário de 3 × o tamanho do box (aqui, R$ 3) para abrir nova coluna.","r":"Murphy, cap. 11"},{"id":"c5","t":"t1","q":"A escala logarítmica é mais indicada que a aritmética quando:","o":["O ativo teve grandes variações percentuais ao longo de um período longo","O gráfico mostra apenas um dia de negociação","O ativo tem preço sempre constante","Queremos ver o volume em vez do preço"],"c":0,"e":"Na escala log, distâncias iguais representam variações percentuais iguais, o que permite comparar movimentos de magnitudes diferentes ao longo de anos.","r":"Murphy, cap. 3"},{"id":"c6","t":"t1","q":"Numa escala logarítmica, a distância vertical entre R$ 10 e R$ 20 é igual à distância entre:","o":["R$ 50 e R$ 100","R$ 20 e R$ 30","R$ 90 e R$ 100","R$ 10 e R$ 15"],"c":0,"e":"Ambos são altas de 100%. Na escala log, iguais variações percentuais têm a mesma distância.","r":"Murphy, cap. 3"},{"id":"c7","t":"t1","q":"Para estudar o histórico de um contrato futuro por vários anos, o analista costuma usar:","o":["Um gráfico contínuo (perpétuo), que junta os vencimentos sucessivos","Apenas o gráfico do contrato que vence no mês corrente","O gráfico do ativo à vista com escala aritmética obrigatória","Somente o gráfico semanal do vencimento mais longo"],"c":0,"e":"Contratos futuros vencem; para análise de longo prazo usa-se a série contínua (com ou sem ajuste das diferenças entre vencimentos).","r":"Programa CT1 1.11; Murphy cap. 8"},{"id":"c8","t":"t1","q":"Corrigir uma série histórica de preços pela inflação é útil principalmente para:","o":["Comparar níveis de preço em termos reais ao longo de muitos anos","Calcular o IFR de 14 períodos","Identificar candles de reversão","Reduzir o volume negociado"],"c":0,"e":"Em séries longas, especialmente em países com inflação alta, a correção mostra se um topo nominal também é um topo em termos reais.","r":"Programa CT1 1.9"},{"id":"c9","t":"t1","q":"A expressão \"a média das opiniões\", usada na análise técnica, se refere a:","o":["O preço de mercado como resultado do consenso de compradores e vendedores","A média aritmética das recomendações de analistas fundamentalistas","O preço médio do dia ponderado pelo volume","A média móvel de 200 períodos"],"c":0,"e":"O preço reflete a soma das expectativas de todos os participantes; o técnico parte desse consenso.","r":"Programa CT1 1.6"},{"id":"c10","t":"t1","q":"Sobre a influência das notícias na análise técnica, é correto afirmar que:","o":["O técnico considera que a reação do preço à notícia é o que importa, pois o mercado já desconta as informações","O técnico deve ignorar o preço quando surge uma notícia relevante","Notícias não afetam preços no curto prazo","Toda notícia positiva produz necessariamente alta"],"c":0,"e":"Para o técnico, o mercado desconta as informações; a forma como o preço reage (e não a notícia em si) traz a informação útil.","r":"Programa CT1 1.4"},{"id":"c11","t":"t1","q":"Na gestão passiva de investimentos, o gestor:","o":["Procura replicar o desempenho de um índice de referência","Faz giro frequente da carteira buscando superar o índice","Usa exclusivamente análise técnica intradiária","Opera apenas derivativos alavancados"],"c":0,"e":"A gestão passiva replica um benchmark; a ativa tenta superá-lo, e é nela que a análise técnica costuma ser usada.","r":"Programa CT1 1.2"},{"id":"c12","t":"t1","q":"Um gráfico de 60 minutos é chamado de:","o":["Gráfico intradiário","Gráfico semanal","Gráfico de longo prazo","Gráfico de ponto e figura"],"c":0,"e":"Gráficos com períodos menores que um dia (1, 5, 15, 60 minutos) são intradiários.","r":"Programa CT1 1.8"},{"id":"c13","t":"t1","q":"Na análise com vários tempos gráficos, a prática recomendada é:","o":["Identificar a tendência no tempo maior e buscar o ponto de entrada no tempo menor","Usar apenas o gráfico de 1 minuto","Ignorar o semanal quando o diário mostra tendência","Operar contra a tendência do tempo maior sempre que houver sinal no menor"],"c":0,"e":"A abordagem top-down (ex.: semanal → diário → 60 min) alinha a operação com a tendência maior e refina a entrada.","r":"Murphy cap. 15; Elder"},{"id":"c14","t":"t2","q":"Segundo a Teoria de Dow, o mercado tem três tendências. A tendência primária costuma durar:","o":["De um a vários anos","De algumas horas a um dia","Exatamente três semanas","Menos de uma semana"],"c":0,"e":"Primária: mais de um ano; secundária: de três semanas a três meses; menor: menos de três semanas.","r":"Murphy cap. 2"},{"id":"c15","t":"t2","q":"Para Dow, as correções secundárias costumam retraçar, do movimento anterior:","o":["Entre um terço e dois terços (com frequência cerca de metade)","Exatamente 100%","Menos de 5%","Sempre 61,8%"],"c":0,"e":"As reações secundárias recuperam tipicamente de 33% a 66% do movimento primário anterior, frequentemente perto de 50%.","r":"Murphy cap. 2"},{"id":"c16","t":"t2","q":"As três fases de uma tendência primária de alta, segundo Dow, são:","o":["Acumulação, participação pública (alta) e distribuição","Pânico, euforia e acumulação","Impulso, correção e consolidação","Rompimento, pullback e exaustão"],"c":0,"e":"Na acumulação os mais informados compram; na fase pública os seguidores de tendência entram; na distribuição os primeiros vendem.","r":"Murphy cap. 2"},{"id":"c17","t":"t2","q":"Pelo princípio da confirmação mútua de Dow, uma tendência de alta só é confirmada quando:","o":["Os índices industrial e de transportes sinalizam na mesma direção","O volume cai durante a alta","O índice rompe a média de 200 dias","A curva de juros fica invertida"],"c":0,"e":"Dow exigia que as duas médias (industrial e transportes) confirmassem o sinal para validar a tendência.","r":"Murphy cap. 2"},{"id":"c18","t":"t2","q":"Sobre o volume, a Teoria de Dow afirma que:","o":["O volume deve confirmar a tendência, aumentando a favor do movimento principal","O volume é a principal ferramenta para dar sinais de compra","O volume deve diminuir na direção da tendência","O volume não tem relação com a tendência"],"c":0,"e":"Para Dow o volume é secundário, mas deve confirmar: numa alta, aumenta nas subidas e diminui nas correções.","r":"Murphy cap. 2"},{"id":"c19","t":"t2","q":"Segundo Dow, uma tendência permanece em vigor até que:","o":["Haja sinais claros de sua reversão","O preço toque a média de 9 períodos","O volume do dia seja o menor do mês","Haja um candle de alta"],"c":0,"e":"Princípio da continuidade: a tendência vale até um sinal definitivo de reversão, o que justifica operar a favor dela.","r":"Murphy cap. 2"},{"id":"c20","t":"t2","q":"Uma tendência de alta, no conceito de Dow, é caracterizada por:","o":["Topos e fundos sucessivamente mais altos","Topos mais baixos e fundos mais altos","Topos e fundos sucessivamente mais baixos","Preço sempre acima da média de 200 dias"],"c":0,"e":"Alta = topos e fundos ascendentes; baixa = topos e fundos descendentes; lateral = topos e fundos no mesmo nível.","r":"Murphy cap. 4"},{"id":"c21","t":"t2","q":"Uma das críticas à Teoria de Dow é que:","o":["Os sinais costumam vir tarde, depois de boa parte do movimento","Ela não considera tendências","Ela proíbe o uso de gráficos","Ela só funciona para opções"],"c":0,"e":"Por exigir confirmação, Dow perde o início e o fim dos movimentos; ela busca capturar o \"miolo\" da tendência.","r":"Murphy cap. 2"},{"id":"c22","t":"t2","q":"Para Dow, o índice que reflete o mercado e deve ser usado na análise usa, preferencialmente, o preço de:","o":["Fechamento","Abertura","Máxima do dia","Média entre máxima e mínima"],"c":0,"e":"Dow considerava só os fechamentos; movimentos intradiários que não se confirmam no fechamento não valem.","r":"Murphy cap. 2"},{"id":"c23","t":"t3","q":"Uma linha de tendência de alta (LTA) é traçada ligando:","o":["Pelo menos dois fundos ascendentes","Dois topos descendentes","O fechamento de hoje à média de 200 dias","Os volumes máximos de cada mês"],"c":0,"e":"A LTA liga fundos ascendentes e é validada pelo toque em um terceiro fundo; a LTB liga topos descendentes.","r":"Murphy cap. 4"},{"id":"c24","t":"t3","q":"Quanto mais vezes uma linha de tendência é testada sem ser rompida:","o":["Mais significativa ela se torna","Menos importante ela fica","Mais provável é que o volume diminua","Mais fácil é que ela vire linha de retorno"],"c":0,"e":"A importância da linha cresce com o número de toques e com o tempo em que permanece válida.","r":"Murphy cap. 4"},{"id":"c25","t":"t3","q":"Uma linha de tendência muito inclinada (íngreme):","o":["Tende a ser rompida com facilidade e a ser substituída por outra mais suave","É mais confiável do que uma linha mais suave","Nunca é rompida","Indica obrigatoriamente o fim da tendência"],"c":0,"e":"Linhas muito íngremes não são sustentáveis; o rompimento costuma levar a ajuste do ângulo (linhas em leque), não necessariamente à reversão.","r":"Murphy cap. 4"},{"id":"c26","t":"t3","q":"O princípio da inversão de polaridade diz que:","o":["Um suporte rompido tende a virar resistência, e uma resistência rompida tende a virar suporte","O suporte nunca é rompido","Após um rompimento o volume deve cair a zero","A tendência de alta vira automaticamente tendência de baixa"],"c":0,"e":"Rompido, o antigo suporte passa a funcionar como resistência (e vice-versa), por causa da memória dos participantes.","r":"Murphy cap. 4"},{"id":"c27","t":"t3","q":"Um canal de alta é formado por:","o":["Uma LTA e uma linha paralela traçada pelos topos (linha de retorno)","Duas linhas que convergem para um ponto","Uma média móvel e o seu desvio padrão","Um topo duplo e um fundo duplo"],"c":0,"e":"Canal = linha de tendência + linha de retorno paralela. Falhar em atingir a linha de retorno pode sinalizar perda de força.","r":"Murphy cap. 4"},{"id":"c28","t":"t3","q":"Num canal de alta, quando o preço não consegue chegar à linha de retorno:","o":["Pode ser um sinal de enfraquecimento e de rompimento da linha de tendência","É um sinal de aceleração da alta","Indica que o canal virou de baixa necessariamente","Não tem nenhum significado"],"c":0,"e":"A falha em atingir o lado superior do canal sugere perda de força e aumenta a chance de rompimento da linha inferior.","r":"Murphy cap. 4"},{"id":"c29","t":"t3","q":"Para considerar válido o rompimento de uma linha de tendência, muitos analistas usam o filtro:","o":["De preço (ex.: fechamento além da linha por uma porcentagem) ou de tempo (ex.: dois fechamentos seguidos)","De volume zero no dia do rompimento","Apenas de uma barra intradiária ultrapassando a linha","Da mudança de cor do candle anterior"],"c":0,"e":"Filtros de 1% a 3% ou de dois dias evitam rompimentos falsos.","r":"Murphy cap. 4"},{"id":"c30","t":"t3","q":"Um suporte é tanto mais forte quanto:","o":["Maior o volume negociado e maior o tempo em que o preço permaneceu na região","Menor o volume negociado na região","Mais distante ele está dos preços atuais","Menos vezes ele foi testado"],"c":0,"e":"Volume alto e permanência longa na região (muitos participantes posicionados) fortalecem suportes e resistências.","r":"Murphy cap. 4"},{"id":"c31","t":"t3","q":"Números redondos (ex.: R$ 50,00 ou 200.000 pontos) costumam:","o":["Funcionar como suportes e resistências psicológicos","Ser ignorados pelos participantes","Indicar gaps de exaustão","Representar médias móveis"],"c":0,"e":"Ordens e alvos se concentram em números redondos, que viram barreiras psicológicas.","r":"Murphy cap. 4"},{"id":"c32","t":"t3","q":"Após o rompimento de uma resistência, o retorno do preço para testar o nível rompido é chamado de:","o":["Pullback","Gap de fuga","Exaustão","Divergência"],"c":0,"e":"Pullback (ou throwback) é o reteste da região rompida, que então deve atuar como suporte.","r":"Murphy cap. 4"},{"id":"c33","t":"t3","q":"Uma tendência lateral (trading range) é caracterizada por:","o":["Topos e fundos aproximadamente no mesmo nível","Topos e fundos ascendentes","Topos descendentes e fundos ascendentes, sempre","Preço sempre acima da média móvel"],"c":0,"e":"Na lateralidade o preço oscila entre suporte e resistência horizontais; indicadores rastreadores dão muitos sinais falsos.","r":"Murphy cap. 4"},{"id":"c34","t":"t3","q":"A linha de retorno (ou linha de canal) em uma tendência de baixa é traçada:","o":["Pelos fundos, paralela à LTB","Pelos topos, paralela à LTA","Pela média dos fechamentos","Pelo volume máximo"],"c":0,"e":"Na baixa a LTB liga topos; a paralela pelos fundos é a linha de retorno.","r":"Murphy cap. 4"},{"id":"c35","t":"t4","q":"O ombro-cabeça-ombro (OCO) é uma figura de:","o":["Reversão de alta para baixa","Continuação de alta","Continuação de baixa","Indefinição, sem direção"],"c":0,"e":"O OCO aparece em topos e indica reversão; o OCO invertido aparece em fundos.","r":"Murphy cap. 5; Edwards & Magee"},{"id":"c36","t":"t4","q":"No OCO, a linha que liga os dois fundos entre os ombros e a cabeça chama-se:","o":["Linha de pescoço","Linha de retorno","Linha de sinal","Banda superior"],"c":0,"e":"O rompimento da linha de pescoço confirma o padrão.","r":"Murphy cap. 5"},{"id":"c37","t":"t4","q":"O objetivo mínimo de preço de um OCO é obtido:","o":["Projetando a distância entre a cabeça e a linha de pescoço a partir do ponto de rompimento","Somando os dois ombros","Calculando 61,8% da altura da cabeça","Usando a média de 200 dias"],"c":0,"e":"Mede-se a altura da cabeça até a linha de pescoço e projeta-se a partir do rompimento.","r":"Murphy cap. 5"},{"id":"c38","t":"t4","q":"Num OCO de topo clássico, o volume costuma:","o":["Ser maior no ombro esquerdo e diminuir na cabeça e no ombro direito, aumentando no rompimento","Ser maior no ombro direito","Ser constante","Diminuir no rompimento da linha de pescoço"],"c":0,"e":"A queda de volume nos picos mostra perda de força compradora; o aumento no rompimento confirma.","r":"Murphy cap. 5; Edwards & Magee"},{"id":"c39","t":"t4","q":"O topo duplo é confirmado quando:","o":["O preço fecha abaixo do fundo intermediário entre os dois topos","O segundo topo é igual ao primeiro","O volume do segundo topo é maior","O preço volta à máxima anterior"],"c":0,"e":"Sem o rompimento do vale intermediário, os dois topos são só uma resistência.","r":"Murphy cap. 5"},{"id":"c40","t":"t4","q":"O triângulo simétrico é, em geral, classificado como figura de:","o":["Continuação","Reversão obrigatória","Exaustão","Clímax"],"c":0,"e":"Triângulos costumam ser de continuação; o rompimento costuma ocorrer entre metade e três quartos do caminho até o vértice.","r":"Murphy cap. 6"},{"id":"c41","t":"t4","q":"O triângulo ascendente tem:","o":["Linha superior horizontal e linha inferior ascendente","Linha superior descendente e inferior horizontal","Duas linhas divergentes","Duas linhas paralelas inclinadas para baixo"],"c":0,"e":"Resistência horizontal e fundos mais altos: viés de rompimento para cima.","r":"Murphy cap. 6"},{"id":"c42","t":"t4","q":"A bandeira de alta é caracterizada por:","o":["Um mastro de alta forte seguido de um pequeno canal contrário à tendência, com volume em queda","Um movimento lateral longo de vários anos","Duas linhas convergentes que apontam para cima, sempre de reversão","Um gap de exaustão seguido de queda"],"c":0,"e":"Bandeiras e flâmulas são pausas curtas após movimentos fortes; o alvo projeta o tamanho do mastro.","r":"Murphy cap. 6"},{"id":"c43","t":"t4","q":"Na bandeira, o objetivo de preço é calculado projetando:","o":["O tamanho do mastro a partir do ponto de rompimento da bandeira","A largura da bandeira","61,8% do mastro","A distância até a média de 200 dias"],"c":0,"e":"Diz-se que a bandeira \"tremula no meio do mastro\": o movimento após o rompimento tende a repetir o mastro.","r":"Murphy cap. 6"},{"id":"c44","t":"t4","q":"A cunha (wedge) se diferencia do triângulo porque:","o":["As duas linhas apontam para a mesma direção (ambas sobem ou ambas descem)","Tem uma linha horizontal","Não tem linhas convergentes","É sempre de continuação de alta"],"c":0,"e":"Cunha ascendente tem viés de baixa; cunha descendente tem viés de alta.","r":"Murphy cap. 6"},{"id":"c45","t":"t4","q":"Uma cunha ascendente que aparece numa tendência de alta costuma indicar:","o":["Possível reversão para baixa","Aceleração da alta","Formação de topo duplo","Gap de fuga"],"c":0,"e":"Topos e fundos subindo cada vez menos mostram perda de força; o rompimento costuma ser para baixo.","r":"Murphy cap. 6"},{"id":"c46","t":"t4","q":"O gap que ocorre no início de um novo movimento, rompendo uma área de congestão com volume alto, é o:","o":["Gap de rompimento (breakaway)","Gap comum","Gap de exaustão","Gap de ilha"],"c":0,"e":"O breakaway marca o início do movimento e costuma não ser fechado logo.","r":"Murphy cap. 4"},{"id":"c47","t":"t4","q":"O gap de fuga (ou de medida) costuma aparecer:","o":["Aproximadamente no meio do movimento","No início de uma lateralidade","Apenas no fim da tendência","Somente em gráficos semanais"],"c":0,"e":"Por aparecer perto da metade do movimento, ele é usado para projetar o restante.","r":"Murphy cap. 4"},{"id":"c48","t":"t4","q":"Um gap de exaustão seguido por um gap na direção contrária, isolando alguns pregões, forma:","o":["Uma ilha de reversão","Um triângulo","Uma bandeira","Um canal"],"c":0,"e":"A ilha de reversão é sinal forte de mudança de direção.","r":"Murphy cap. 4"},{"id":"c49","t":"t4","q":"O gap comum costuma:","o":["Aparecer em mercados laterais ou de baixa liquidez e ser fechado rapidamente","Indicar sempre o início de tendência forte","Nunca ser fechado","Aparecer só após balanços"],"c":0,"e":"Gaps comuns têm pouco significado e tendem a ser preenchidos.","r":"Murphy cap. 4"},{"id":"c50","t":"t4","q":"O retângulo é uma figura em que:","o":["O preço oscila entre duas linhas horizontais paralelas","As linhas convergem","As linhas divergem formando um megafone","Só existe um topo e um fundo"],"c":0,"e":"Geralmente de continuação; o alvo projeta a altura do retângulo a partir do rompimento.","r":"Murphy cap. 6"},{"id":"c51","t":"t4","q":"O topo arredondado (saucer) caracteriza-se por:","o":["Uma mudança gradual de direção, com volume também em forma de \"U\"","Um único dia de reversão com gap","Duas linhas convergentes","Um OCO com três cabeças"],"c":0,"e":"É uma reversão lenta; o volume costuma acompanhar o formato.","r":"Murphy cap. 5"},{"id":"c52","t":"t4","q":"O \"megafone\" (formação de alargamento) é considerado:","o":["Uma figura de topo, com volatilidade crescente e viés de baixa","Uma figura de continuação de baixa volatilidade","Uma bandeira de alta","Um sinal de compra seguro"],"c":0,"e":"Topos cada vez mais altos e fundos cada vez mais baixos mostram mercado fora de controle, comum em topos.","r":"Murphy cap. 6"},{"id":"c53","t":"t5","q":"Na Teoria das Ondas de Elliott, um ciclo completo de mercado é formado por:","o":["Cinco ondas a favor da tendência e três ondas corretivas","Três ondas a favor e cinco contra","Duas ondas impulsivas e duas corretivas","Nove ondas impulsivas"],"c":0,"e":"5 ondas impulsivas (1 a 5) seguidas de 3 corretivas (A, B, C).","r":"Frost & Prechter; Murphy cap. 13"},{"id":"c54","t":"t5","q":"Qual regra NÃO pode ser violada numa onda impulsiva de Elliott?","o":["A onda 3 não pode ser a mais curta entre as ondas 1, 3 e 5","A onda 5 deve ser sempre a mais longa","A onda 2 deve retraçar exatamente 50%","A onda 4 deve sempre formar uma bandeira"],"c":0,"e":"Regras: a 2 não retraça mais de 100% da 1; a 3 nunca é a mais curta; a 4 não entra na área de preço da 1.","r":"Frost & Prechter"},{"id":"c55","t":"t5","q":"Numa onda impulsiva de alta, a onda 4:","o":["Não deve sobrepor o topo da onda 1","Deve sempre retraçar 100% da onda 3","Deve ser maior que a onda 3","Deve ter volume maior que a onda 3"],"c":0,"e":"A regra de não sobreposição (no mercado à vista, sem alavancagem) diz que o fundo da 4 fica acima do topo da 1.","r":"Frost & Prechter"},{"id":"c56","t":"t5","q":"A onda 2 de um impulso de alta:","o":["Não pode retraçar mais de 100% da onda 1","Deve retraçar exatamente 38,2% da onda 1","Deve superar o topo da onda 1","Sempre forma um triângulo"],"c":0,"e":"Se a 2 cair abaixo do início da 1, a contagem está errada.","r":"Frost & Prechter"},{"id":"c57","t":"t5","q":"Segundo Elliott, a onda que costuma ser a mais longa e com maior volume é a:","o":["Onda 3","Onda 1","Onda 5","Onda B"],"c":0,"e":"A onda 3 costuma ser a mais forte, com o maior envolvimento do público.","r":"Frost & Prechter; Murphy cap. 13"},{"id":"c58","t":"t5","q":"O princípio da alternância de Elliott sugere que:","o":["Se a onda 2 for uma correção simples e aguda, a onda 4 tende a ser complexa e lateral (e vice-versa)","As ondas 1 e 5 têm sempre o mesmo tamanho","A onda A e a onda C são sempre triângulos","O volume alterna a cada pregão"],"c":0,"e":"Alternância: correções 2 e 4 costumam diferir em forma.","r":"Frost & Prechter"},{"id":"c59","t":"t5","q":"Uma correção do tipo zigue-zague tem a estrutura:","o":["5-3-5","3-3-5","3-3-3-3-3","5-5-5"],"c":0,"e":"Zigue-zague: A em 5, B em 3, C em 5. A plana (flat) é 3-3-5 e o triângulo é 3-3-3-3-3.","r":"Frost & Prechter"},{"id":"c60","t":"t5","q":"Os triângulos de Elliott costumam aparecer:","o":["Na onda 4 ou na onda B","Na onda 1 ou na onda 3","Somente na onda 5","Apenas em fundos de mercado"],"c":0,"e":"Triângulos são padrões de continuação que precedem o último movimento da sequência.","r":"Frost & Prechter"},{"id":"c61","t":"t5","q":"A razão de ouro, base dos níveis de Fibonacci, é aproximadamente:","o":["1,618 (e seu inverso 0,618)","1,414","3,14","2,718"],"c":0,"e":"Cada número da sequência dividido pelo anterior tende a 1,618; pelo seguinte, a 0,618.","r":"Murphy cap. 13"},{"id":"c62","t":"t5","q":"Os níveis de retração de Fibonacci mais usados são:","o":["38,2%, 50% e 61,8%","10%, 20% e 30%","25%, 75% e 100% apenas","33%, 66% e 99%"],"c":0,"e":"O 50% não é razão de Fibonacci, mas vem de Dow e é usado junto.","r":"Murphy cap. 13"},{"id":"c63","t":"t5","q":"Uma ação subiu de R$ 20 para R$ 30. A retração de 61,8% desse movimento fica em aproximadamente:","o":["R$ 23,82","R$ 26,18","R$ 18,20","R$ 16,18"],"c":0,"e":"Movimento de R$ 10; 61,8% = R$ 6,18; 30 − 6,18 = R$ 23,82.","r":"Cálculo de Fibonacci"},{"id":"c64","t":"t5","q":"Pela relação de Fibonacci, é comum projetar a onda 3 como:","o":["1,618 vez o tamanho da onda 1","0,236 vez a onda 1","Exatamente igual à onda 2","A metade da onda 5"],"c":0,"e":"Projeções frequentes: onda 3 ≈ 1,618 × onda 1; onda 5 ≈ onda 1 quando a 3 é estendida.","r":"Frost & Prechter"},{"id":"c65","t":"t5","q":"Quando uma das ondas impulsivas é estendida (muito maior), em geral:","o":["As outras duas tendem a ter tamanho parecido","Todas as três ficam iguais","A onda 4 passa a ser a maior","A contagem passa a ter 9 ondas corretivas"],"c":0,"e":"Diretriz da igualdade: se a 3 é estendida, a 1 e a 5 tendem a ser semelhantes.","r":"Frost & Prechter"},{"id":"c66","t":"t6","q":"Num candle, o \"corpo real\" é a distância entre:","o":["A abertura e o fechamento","A máxima e a mínima","O fechamento de hoje e o de ontem","A mínima e o fechamento"],"c":0,"e":"As sombras vão do corpo até a máxima e a mínima.","r":"Nison"},{"id":"c67","t":"t6","q":"Um marubozu de alta (branco/verde) é um candle:","o":["De corpo longo, sem sombras: abre na mínima e fecha na máxima","De corpo pequeno com sombras longas","Em que abertura e fechamento são iguais","Com sombra inferior longa e corpo no topo"],"c":0,"e":"Mostra domínio total dos compradores no período.","r":"Nison"},{"id":"c68","t":"t6","q":"O doji é o candle em que:","o":["A abertura e o fechamento são iguais ou quase iguais","Não há sombras","A sombra inferior é três vezes o corpo","O corpo é muito longo"],"c":0,"e":"Indica indecisão; ganha importância após tendências fortes.","r":"Nison"},{"id":"c69","t":"t6","q":"O martelo é um padrão de reversão que aparece:","o":["Depois de uma tendência de baixa, com corpo pequeno no alto e sombra inferior longa","No topo de uma alta, com sombra superior longa","Em qualquer ponto, sem importar a tendência","Somente em gráficos semanais"],"c":0,"e":"Sombra inferior de pelo menos duas vezes o corpo, pouca ou nenhuma sombra superior, após queda.","r":"Nison"},{"id":"c70","t":"t6","q":"O enforcado (homem enforcado) tem o mesmo formato do martelo, mas:","o":["Aparece depois de uma tendência de alta e sinaliza possível topo","Aparece depois de uma baixa e sinaliza fundo","Tem corpo muito longo","Só vale se for vermelho"],"c":0,"e":"O contexto muda o significado: martelo em fundos, enforcado em topos (pede confirmação).","r":"Nison"},{"id":"c71","t":"t6","q":"A estrela cadente (shooting star) aparece:","o":["No topo, com corpo pequeno embaixo e sombra superior longa","No fundo, com sombra inferior longa","No meio de lateralidade, com corpo longo","Somente com gap de alta no dia seguinte"],"c":0,"e":"Mostra rejeição de preços mais altos após uma alta.","r":"Nison"},{"id":"c72","t":"t6","q":"O martelo invertido aparece:","o":["Depois de uma queda, com corpo pequeno embaixo e sombra superior longa, pedindo confirmação","Depois de uma alta, com sombra inferior longa","Sempre com gap de baixa","Como sinal de continuação de baixa"],"c":0,"e":"Tem o formato da estrela cadente, mas no fundo; precisa de confirmação no candle seguinte.","r":"Nison"},{"id":"c73","t":"t6","q":"O padrão de engolfo de alta é formado por:","o":["Um candle de baixa seguido de um candle de alta cujo corpo engole totalmente o corpo anterior","Dois dojis seguidos","Um candle de alta seguido de um menor de baixa","Três candles de alta pequenos"],"c":0,"e":"Aparece depois de queda; o segundo corpo cobre todo o primeiro.","r":"Nison"},{"id":"c74","t":"t6","q":"O harami (\"mulher grávida\") é formado quando:","o":["Um candle de corpo pequeno fica contido dentro do corpo do candle anterior, que é grande","O segundo candle engole o primeiro","Há um gap entre os dois candles","Três candles formam uma estrela"],"c":0,"e":"Indica perda de força da tendência; o harami cross tem um doji como segundo candle.","r":"Nison"},{"id":"c75","t":"t6","q":"A nuvem negra (dark cloud cover) é um padrão de topo em que o segundo candle:","o":["Abre acima da máxima anterior e fecha abaixo do meio do corpo do candle de alta anterior","Abre abaixo e fecha acima do candle anterior","É um doji","Fecha acima da máxima anterior"],"c":0,"e":"Quanto mais fundo ele penetrar no corpo anterior, mais forte o sinal.","r":"Nison"},{"id":"c76","t":"t6","q":"A linha penetrante (piercing line) é o oposto da nuvem negra e aparece:","o":["No fundo: abre abaixo da mínima anterior e fecha acima do meio do corpo de baixa anterior","No topo: abre acima e fecha abaixo","No meio de uma lateralidade","Somente com volume baixo"],"c":0,"e":"Padrão de reversão de baixa para alta.","r":"Nison"},{"id":"c77","t":"t6","q":"A estrela da manhã (morning star) é composta por:","o":["Candle de baixa longo, candle pequeno com gap para baixo e candle de alta que fecha bem dentro do primeiro","Três candles de alta seguidos","Um doji entre dois candles de baixa","Candle de alta, gap para cima e candle de baixa"],"c":0,"e":"Padrão de três candles de reversão em fundos; a estrela da tarde é o equivalente em topos.","r":"Nison"},{"id":"c78","t":"t6","q":"No bebê abandonado de baixa, o candle do meio:","o":["É um doji isolado por gaps dos dois lados (das sombras)","É um marubozu","Engolfa os dois vizinhos","Não tem gap em relação aos outros"],"c":0,"e":"É uma versão rara e forte da estrela da tarde, com gaps incluindo as sombras.","r":"Nison"},{"id":"c79","t":"t6","q":"O spinning top (pião) é um candle de:","o":["Corpo pequeno com sombras de tamanho parecido, indicando indecisão","Corpo longo sem sombras","Sombra inferior muito longa e sem sombra superior","Abertura igual à máxima"],"c":0,"e":"Mostra equilíbrio entre compradores e vendedores.","r":"Nison"},{"id":"c80","t":"t6","q":"O guarda-chuva japonês é o nome dado aos candles:","o":["Martelo e enforcado (corpo pequeno no topo e sombra inferior longa)","Estrela cadente e martelo invertido","Doji e spinning top","Engolfo e harami"],"c":0,"e":"Mesmo formato, significados diferentes conforme o contexto.","r":"Nison"},{"id":"c81","t":"t6","q":"A doji star é:","o":["Um doji que abre com gap em relação ao corpo longo do candle anterior, após uma tendência","Um doji com volume muito alto","Dois dojis seguidos","Um doji que aparece no meio de uma bandeira"],"c":0,"e":"Sinaliza possível reversão; pede confirmação.","r":"Nison"},{"id":"c82","t":"t7","q":"Indicadores do tipo \"rastreador\" (seguidores de tendência) funcionam melhor em:","o":["Mercados com tendência definida","Mercados laterais","Dias de baixa liquidez apenas","Gráficos de ponto e figura apenas"],"c":0,"e":"Rastreadores (médias, MACD) acompanham tendência; osciladores (IFR, estocástico) funcionam melhor em lateralidade.","r":"Murphy cap. 9 e 10"},{"id":"c83","t":"t7","q":"A média móvel exponencial se diferencia da aritmética porque:","o":["Dá mais peso aos preços mais recentes","Dá o mesmo peso a todos os preços","Usa apenas os preços de abertura","Não pode ser usada em gráficos diários"],"c":0,"e":"A exponencial reage mais rápido às mudanças de preço.","r":"Murphy cap. 9"},{"id":"c84","t":"t7","q":"No cruzamento de duas médias móveis, o sinal de compra clássico ocorre quando:","o":["A média curta cruza a média longa para cima","A média longa cruza a curta para cima","As duas médias ficam paralelas","O preço toca a média longa por baixo e recua"],"c":0,"e":"Ex.: média de 9 cruzando a de 21 para cima. Em lateralidade gera muitos sinais falsos.","r":"Murphy cap. 9"},{"id":"c85","t":"t7","q":"O MACD é calculado como:","o":["A diferença entre duas médias móveis exponenciais (tipicamente 12 e 26), com uma linha de sinal (média de 9 do MACD)","A razão entre altas e baixas de 14 períodos","A distância do preço até a máxima de 14 períodos","O desvio padrão de 20 períodos"],"c":0,"e":"O histograma mostra a diferença entre o MACD e a sua linha de sinal.","r":"Murphy cap. 10; Appel"},{"id":"c86","t":"t7","q":"As Bandas de Bollinger padrão usam:","o":["Média móvel de 20 períodos e bandas a 2 desvios padrão","Média de 9 e bandas fixas de 5%","Média de 200 e bandas a 1 desvio","Duas médias exponenciais de 12 e 26"],"c":0,"e":"O estreitamento das bandas (squeeze) mostra baixa volatilidade, que costuma anteceder movimentos fortes.","r":"Murphy cap. 9; Bollinger"},{"id":"c87","t":"t7","q":"O IFR (índice de força relativa) de Wilder varia:","o":["Entre 0 e 100, com 70 e 30 como níveis clássicos de sobrecompra e sobrevenda","Entre −1 e +1","Sem limites","Entre 0 e 1.000"],"c":0,"e":"Calculado com 14 períodos no padrão de Wilder.","r":"Murphy cap. 10"},{"id":"c88","t":"t7","q":"A fórmula do IFR é:","o":["100 − 100 / (1 + média dos ganhos / média das perdas)","Fechamento − fechamento de n períodos atrás","(Fechamento − mínima) / (máxima − mínima) × 100","Média de 12 − média de 26"],"c":0,"e":"A razão média de alta/baixa (RS) é transformada para a escala de 0 a 100.","r":"Wilder; Murphy cap. 10"},{"id":"c89","t":"t7","q":"O indicador de momento (momentum) de 10 períodos é calculado como:","o":["Fechamento atual menos o fechamento de 10 períodos atrás","Média dos últimos 10 fechamentos","Volume atual dividido pelo volume médio","Máxima de 10 períodos menos a mínima"],"c":0,"e":"Mede a velocidade do movimento; a taxa de variação (ROC) usa a razão em vez da diferença.","r":"Murphy cap. 10"},{"id":"c90","t":"t7","q":"O estocástico lento (%K e %D) compara:","o":["O fechamento com a faixa entre máxima e mínima de um período","O volume com a média de volume","Duas médias exponenciais","O preço com o índice de mercado"],"c":0,"e":"%K = (fechamento − mínima de n)/(máxima de n − mínima de n) × 100; %D é a média do %K. Níveis 80/20.","r":"Murphy cap. 10; Lane"},{"id":"c91","t":"t7","q":"Uma divergência de baixa ocorre quando:","o":["O preço faz topo mais alto e o oscilador faz topo mais baixo","O preço faz fundo mais baixo e o oscilador também","O preço e o oscilador sobem juntos","O volume e o preço caem juntos"],"c":0,"e":"Mostra perda de força da alta; a divergência de alta é o contrário em fundos.","r":"Murphy cap. 10"},{"id":"c92","t":"t7","q":"\"Sobrecomprado\" significa que:","o":["O preço subiu muito rápido e o oscilador está no extremo superior, o que pede cautela, não venda automática","O ativo deve ser vendido imediatamente","O volume está no máximo do ano","O preço está abaixo da média de 200 dias"],"c":0,"e":"Em tendências fortes o oscilador pode ficar sobrecomprado por muito tempo; o sinal é mais útil com divergência.","r":"Murphy cap. 10"},{"id":"c93","t":"t7","q":"O OBV (on balance volume) é calculado:","o":["Somando o volume nos dias de alta e subtraindo nos dias de baixa","Dividindo o volume pelo preço","Pela média de volume de 20 dias","Pelo número de contratos em aberto"],"c":0,"e":"Criado por Granville; a direção do OBV deve confirmar a do preço.","r":"Murphy cap. 7"},{"id":"c94","t":"t7","q":"Quando o OBV faz topos mais baixos enquanto o preço faz topos mais altos, há:","o":["Divergência negativa, sugerindo distribuição","Confirmação da alta","Sinal de compra imediato","Gap de fuga"],"c":0,"e":"O volume não confirma a alta.","r":"Murphy cap. 7"},{"id":"c95","t":"t7","q":"Médias móveis mais longas (ex.: 200 períodos), em relação às curtas:","o":["Dão menos sinais falsos, mas com mais atraso","Dão mais sinais e mais rápidos","Não têm atraso","Só servem para intraday"],"c":0,"e":"Há sempre troca entre sensibilidade e confiabilidade.","r":"Murphy cap. 9"},{"id":"c96","t":"t8","q":"Numa compra feita após o rompimento de uma resistência, o stop loss costuma ser colocado:","o":["Um pouco abaixo da antiga resistência, que virou suporte, ou do último fundo","Acima da máxima do dia","Exatamente no preço de entrada","A 50% de distância do preço"],"c":0,"e":"O stop técnico vai além do nível que invalida a tese, com uma pequena folga.","r":"Programa CT1 VIII"},{"id":"c97","t":"t8","q":"Um stop móvel (trailing stop) numa compra:","o":["É elevado conforme o preço sobe, protegendo o lucro, e nunca é baixado","É baixado conforme o preço cai","Fica sempre no preço de entrada","Só é usado em vendas a descoberto"],"c":0,"e":"Pode seguir fundos ascendentes, médias móveis ou uma distância fixa (ex.: múltiplo do ATR).","r":"Programa CT1 8.4"},{"id":"c98","t":"t8","q":"Um \"stop para iniciar posições\" (ordem stop de compra) é usado para:","o":["Entrar comprado só se o preço romper um nível acima do preço atual","Sair de uma posição perdedora","Cancelar todas as ordens","Comprar abaixo do preço atual"],"c":0,"e":"É a ordem de start: compra se o preço superar o gatilho, confirmando o rompimento.","r":"Programa CT1 8.5"},{"id":"c99","t":"t8","q":"Colocar o stop exatamente sobre um suporte muito evidente pode ser ruim porque:","o":["Muitas ordens ficam no mesmo ponto e o preço pode furar rapidamente o nível antes de voltar","O suporte nunca é testado","A corretora não aceita ordens nesse nível","O volume sempre cai nesse ponto"],"c":0,"e":"É comum dar uma folga além do nível óbvio para evitar violinadas.","r":"Programa CT1 8.3"},{"id":"c100","t":"t8","q":"Na ordem stop limitada, existe o risco de:","o":["O preço passar do limite e a ordem não ser executada","A ordem ser executada sempre ao preço de mercado","A ordem virar uma compra automática","Não haver gatilho"],"c":0,"e":"O stop limitado dispara no gatilho, mas só executa até o preço limite; em gaps pode ficar sem execução.","r":"Programa CT1 8.1"},{"id":"c101","t":"t8","q":"Um gap de alta que abre acima de uma resistência tende a fazer da região do gap:","o":["Um suporte","Uma nova resistência","Um nível irrelevante","Um alvo de venda obrigatório"],"c":0,"e":"A parte inferior do gap costuma servir de suporte em retestes.","r":"Programa CT1 8.9"},{"id":"c102","t":"t8","q":"O risco por operação no gerenciamento de capital clássico costuma ser limitado a:","o":["Uma pequena porcentagem do capital (ex.: 1% a 2%)","50% do capital","Todo o capital disponível","O valor da margem exigida"],"c":0,"e":"Limitar o risco por trade preserva o capital em sequências de perdas.","r":"Murphy cap. 16; Elder"},{"id":"c103","t":"t8","q":"A relação risco/retorno de uma operação com entrada em R$ 20, stop em R$ 19 e alvo em R$ 23 é:","o":["1 para 3","3 para 1","1 para 1","1 para 2"],"c":0,"e":"Risco de R$ 1 e retorno potencial de R$ 3.","r":"Cálculo"},{"id":"c104","t":"t8","q":"Num sistema com 40% de acerto, ganho médio de R$ 300 e perda média de R$ 100, a expectativa por operação é:","o":["R$ 60","R$ 120","−R$ 20","R$ 200"],"c":0,"e":"0,40 × 300 − 0,60 × 100 = 120 − 60 = R$ 60.","r":"Van Tharp; Elder"},{"id":"c105","t":"t8","q":"Um sistema de trading bem testado deve ser avaliado principalmente por:","o":["Expectativa positiva, rebaixamento máximo (drawdown) e consistência fora da amostra","Apenas a taxa de acerto","O número de indicadores usados","O resultado do melhor mês"],"c":0,"e":"Taxa de acerto alta com perdas grandes pode ter expectativa negativa.","r":"Programa CT1 X"},{"id":"c106","t":"t8","q":"O \"ajuste excessivo\" (overfitting) de um sistema de trading ocorre quando:","o":["Os parâmetros são otimizados demais para o passado e o sistema falha em dados novos","O sistema usa stop móvel","O sistema opera apenas a favor da tendência","O sistema tem poucas regras"],"c":0,"e":"Por isso se testa fora da amostra (walk-forward).","r":"Kirkpatrick"},{"id":"c107","t":"t8","q":"O tamanho de posição para arriscar R$ 500 numa compra com entrada em R$ 50 e stop em R$ 48 é:","o":["250 ações","100 ações","500 ações","1.000 ações"],"c":0,"e":"Risco por ação de R$ 2; R$ 500 ÷ R$ 2 = 250 ações.","r":"Cálculo de position sizing"},{"id":"c108","t":"t9","q":"Numa tendência de alta saudável, o volume deve:","o":["Aumentar nas altas e diminuir nas correções","Diminuir nas altas e aumentar nas correções","Ficar sempre constante","Cair a zero nos topos"],"c":0,"e":"O volume confirma a força da tendência.","r":"Murphy cap. 7"},{"id":"c109","t":"t9","q":"Contratos em aberto (open interest) são:","o":["O número total de contratos de derivativos que ainda não foram liquidados","O volume negociado no dia","O número de negócios realizados","A quantidade de ações em circulação"],"c":0,"e":"Cada contrato em aberto tem um comprado e um vendido.","r":"Murphy cap. 7"},{"id":"c110","t":"t9","q":"Se o preço do futuro sobe, o volume é alto e os contratos em aberto aumentam, a leitura clássica é:","o":["Tendência de alta forte, com entrada de novos compradores","Alta fraca, causada só por recompra de vendidos","Reversão iminente para baixa","Sem significado"],"c":0,"e":"Preço e contratos em aberto subindo juntos: dinheiro novo entrando na direção da alta.","r":"Murphy cap. 7"},{"id":"c111","t":"t9","q":"Preço subindo com contratos em aberto caindo indica, classicamente:","o":["Alta sustentada por recompra de vendidos (short covering), considerada mais fraca","Entrada maciça de novos compradores","Tendência de baixa forte","Aumento da volatilidade implícita"],"c":0,"e":"Os vendidos zerando posição puxam o preço, mas sem dinheiro novo.","r":"Murphy cap. 7"},{"id":"c112","t":"t9","q":"Um clímax de venda é caracterizado por:","o":["Queda acentuada com volume muito acima da média, frequentemente seguida de reversão","Alta lenta com volume baixo","Lateralidade com volume constante","Gap comum sem volume"],"c":0,"e":"Capitulação: todos os vendedores saem de uma vez.","r":"Murphy cap. 7"},{"id":"c113","t":"t9","q":"O rompimento de uma figura gráfica é mais confiável quando ocorre com:","o":["Volume acima da média","Volume abaixo da média","Volume zero","Qualquer volume, pois ele é irrelevante"],"c":0,"e":"Especialmente nos rompimentos para cima o volume deve aumentar.","r":"Murphy cap. 5 e 7"},{"id":"c114","t":"t9","q":"Num mercado de ações, o \"volume\" de um pregão representa:","o":["A quantidade de ações (ou o valor financeiro) negociada no período","O número de acionistas da empresa","Os contratos em aberto","A quantidade de ordens canceladas"],"c":0,"e":"Pode ser medido em quantidade de papéis ou em financeiro.","r":"Murphy cap. 7"},{"id":"c115","t":"t10","q":"A melhor forma de aumentar a confiabilidade de um sinal técnico é:","o":["Buscar a confluência de ferramentas diferentes (ex.: suporte, retração de Fibonacci e candle de reversão no mesmo ponto)","Usar vários osciladores parecidos ao mesmo tempo","Usar só o gráfico de 1 minuto","Seguir apenas notícias"],"c":0,"e":"Ferramentas independentes que apontam para o mesmo nível reforçam o sinal; vários indicadores do mesmo tipo dão informação redundante.","r":"Programa CT1 X; Murphy cap. 18"},{"id":"c116","t":"t10","q":"Usar o IFR, o estocástico e o momento juntos para confirmar um sinal tem a limitação de que:","o":["São todos osciladores de momento e trazem informação parecida (multicolinearidade)","Eles nunca concordam","Eles só funcionam em gráficos semanais","Eles medem volume"],"c":0,"e":"Melhor combinar ferramentas de naturezas diferentes: tendência, momento, volume e padrões.","r":"Kirkpatrick"},{"id":"c117","t":"t10","q":"Numa tendência de alta no semanal, um sinal de sobrevenda no estocástico diário pode ser usado como:","o":["Oportunidade de compra a favor da tendência maior","Sinal de venda a descoberto","Indicação de que a tendência semanal acabou","Algo a ser ignorado sempre"],"c":0,"e":"Princípio do Sistema de Triplo Filtro de Elder: tendência no tempo maior, oscilador no menor.","r":"Elder"},{"id":"c118","t":"t10","q":"Qual combinação está correta quanto à função das ferramentas?","o":["Linhas de tendência e médias indicam direção; osciladores indicam momento; volume confirma","Osciladores indicam direção; médias indicam volume","Volume indica o alvo; candles indicam a tendência primária","Fibonacci define o volume"],"c":0,"e":"Cada ferramenta tem uma função; combiná-las por função evita redundância.","r":"Murphy cap. 18"},{"id":"c119","t":"t10","q":"Os indicadores DeMark (como o TD Sequential) foram desenvolvidos principalmente para:","o":["Identificar pontos de exaustão e possível reversão da tendência","Calcular o valor justo das ações","Medir contratos em aberto","Substituir as médias móveis em tendências"],"c":0,"e":"Contagens de setup (9) e countdown (13) buscam exaustão.","r":"Pearl, DeMark Indicators"}],"cb":[{"id":"b0","t":"b1","q":"O órgão normativo máximo do Sistema Financeiro Nacional é o:","o":["Conselho Monetário Nacional (CMN)","Banco Central do Brasil","Comissão de Valores Mobiliários (CVM)","B3"],"c":0,"e":"O CMN define as diretrizes; o Banco Central e a CVM são órgãos supervisores que executam e fiscalizam.","r":"Lei 4.595/1964"},{"id":"b1","t":"b1","q":"Quem define a meta da taxa Selic é o:","o":["Copom, do Banco Central","Conselho Monetário Nacional","Tesouro Nacional","Ministério do Planejamento"],"c":0,"e":"O Comitê de Política Monetária do BC se reúne 8 vezes por ano; o CMN define a meta de inflação.","r":"BCB"},{"id":"b2","t":"b1","q":"A Comissão de Valores Mobiliários (CVM) é responsável por:","o":["Regular e fiscalizar o mercado de valores mobiliários","Fixar a meta de inflação","Emitir moeda","Fiscalizar seguradoras"],"c":0,"e":"Criada pela Lei 6.385/1976, é autarquia vinculada ao Ministério da Fazenda.","r":"Lei 6.385/1976"},{"id":"b3","t":"b1","q":"A supervisão do mercado de seguros, previdência aberta e capitalização cabe à:","o":["Susep","Previc","CVM","Anbima"],"c":0,"e":"A Previc supervisiona os fundos de pensão (previdência fechada).","r":"Estrutura do SFN"},{"id":"b4","t":"b1","q":"Quem define a meta de inflação que o Banco Central deve perseguir é o:","o":["Conselho Monetário Nacional","Copom","IBGE","Congresso Nacional"],"c":0,"e":"O CMN fixa a meta; o IBGE calcula o IPCA; o Copom usa a Selic para atingir a meta.","r":"Sistema de metas de inflação"},{"id":"b5","t":"b1","q":"O Fundo Garantidor de Créditos (FGC) protege, por CPF e por instituição, depósitos e títulos como CDB até o limite de:","o":["R$ 250 mil","R$ 1 milhão","R$ 50 mil","Ilimitado"],"c":0,"e":"Há ainda um teto global de R$ 1 milhão a cada quatro anos por CPF.","r":"FGC"},{"id":"b6","t":"b1","q":"Uma entidade autorreguladora do mercado de capitais brasileiro, responsável por códigos de melhores práticas de fundos e distribuição, é a:","o":["Anbima","Susep","Previc","Receita Federal"],"c":0,"e":"A Anbima tem autorregulação por adesão; a B3 tem a BSM Supervisão de Mercados.","r":"Autorregulação"},{"id":"b7","t":"b1","q":"O Banco Central NÃO tem entre as suas funções:","o":["Regular os valores mobiliários e as companhias abertas","Executar a política monetária","Supervisionar as instituições financeiras","Administrar as reservas internacionais"],"c":0,"e":"A regulação de valores mobiliários e companhias abertas é da CVM.","r":"Estrutura do SFN"},{"id":"b8","t":"b2","q":"As ações ordinárias (ON) conferem ao acionista:","o":["Direito a voto nas assembleias","Prioridade no recebimento de dividendos, sem voto","Rendimento fixo","Garantia de recompra pela empresa"],"c":0,"e":"As preferenciais (PN) costumam ter prioridade em dividendos e, em geral, não votam.","r":"Lei 6.404/1976, art. 15 a 17"},{"id":"b9","t":"b2","q":"Numa oferta pública inicial (IPO):","o":["A empresa abre o capital e vende ações ao público pela primeira vez","A empresa recompra as próprias ações","A empresa fecha o capital","Os acionistas trocam ações ON por PN"],"c":0,"e":"Ofertas seguintes de uma empresa já listada são chamadas de follow-on.","r":"Mercado primário"},{"id":"b10","t":"b2","q":"A diferença entre mercado primário e secundário é que:","o":["No primário os recursos vão para a empresa emissora; no secundário os investidores negociam entre si","No secundário a empresa recebe o dinheiro","O primário só negocia derivativos","Não há diferença"],"c":0,"e":"A bolsa é essencialmente mercado secundário, que dá liquidez às emissões.","r":"Mercado de capitais"},{"id":"b11","t":"b2","q":"No desdobramento (split) de ações:","o":["O número de ações aumenta e o preço de cada uma cai na mesma proporção, sem alterar o capital","O capital social da empresa aumenta","O acionista recebe dinheiro","O número de ações diminui"],"c":0,"e":"No grupamento (inplit) ocorre o contrário.","r":"Eventos corporativos"},{"id":"b12","t":"b2","q":"A bonificação em ações ocorre quando a empresa:","o":["Incorpora reservas ao capital e distribui novas ações aos acionistas, sem custo","Vende novas ações ao mercado","Paga juros sobre capital próprio","Recompra ações"],"c":0,"e":"O acionista recebe ações gratuitamente na proporção que já possui.","r":"Eventos corporativos"},{"id":"b13","t":"b2","q":"O direito de subscrição permite ao acionista:","o":["Comprar novas ações emitidas pela empresa, na proporção que já possui, a um preço definido","Vender ações à empresa por um preço mínimo","Votar em assembleias","Receber dividendos antecipados"],"c":0,"e":"O direito pode ser exercido ou vendido em bolsa durante o prazo.","r":"Lei 6.404/1976"},{"id":"b14","t":"b2","q":"Os juros sobre capital próprio (JCP) se diferenciam dos dividendos porque:","o":["São dedutíveis como despesa no cálculo do imposto da empresa e têm imposto retido na fonte para o acionista","São isentos para a empresa e para o acionista","Só podem ser pagos a acionistas ON","Não fazem parte da remuneração do acionista"],"c":0,"e":"Por isso o JCP é uma forma de remuneração fiscalmente eficiente para a empresa.","r":"Lei 9.249/1995"},{"id":"b15","t":"b2","q":"O tag along previsto na Lei das S.A. garante aos acionistas minoritários com ações ordinárias, na venda do controle:","o":["Pelo menos 80% do preço pago por ação ao controlador","100% do preço pago ao controlador","50% do preço pago","O valor patrimonial da ação"],"c":0,"e":"Art. 254-A da Lei 6.404. O Novo Mercado exige 100%.","r":"Lei 6.404/1976, art. 254-A"},{"id":"b16","t":"b2","q":"A data a partir da qual a ação passa a ser negociada sem direito a um provento já declarado é chamada de:","o":["Data ex (ex-direito / ex-dividendo)","Data de pagamento","Data de liquidação","Data de registro na CVM"],"c":0,"e":"Quem compra a partir da data ex não recebe aquele provento; o preço costuma ser ajustado.","r":"Eventos corporativos"},{"id":"b17","t":"b2","q":"Os BDRs negociados na B3 são:","o":["Certificados que representam valores mobiliários emitidos no exterior","Ações de empresas brasileiras negociadas nos EUA","Títulos públicos indexados ao dólar","Fundos de renda fixa"],"c":0,"e":"Os ADRs são o contrário: recibos de ações estrangeiras (como as brasileiras) negociados nos EUA.","r":"Mercado de capitais"},{"id":"b18","t":"b2","q":"A liquidação das operações à vista com ações na B3 ocorre em:","o":["D+2","D+0","D+5","D+30"],"c":0,"e":"O financeiro e os títulos são liquidados dois dias úteis após o pregão.","r":"B3"},{"id":"b19","t":"b3","q":"O título público LTN é:","o":["Prefixado e sem pagamento de cupons (paga tudo no vencimento)","Pós-fixado à Selic","Indexado ao IPCA com cupons semestrais","Prefixado com cupons semestrais"],"c":0,"e":"LTN = Tesouro Prefixado; NTN-F = prefixado com juros semestrais; LFT = Tesouro Selic; NTN-B = Tesouro IPCA+.","r":"Tesouro Nacional"},{"id":"b20","t":"b3","q":"Se a taxa de juros de mercado sobe, o preço (PU) de um título prefixado:","o":["Cai","Sobe","Fica igual","Dobra"],"c":0,"e":"O PU é o valor presente do fluxo; taxa maior desconta mais. Por isso títulos prefixados longos oscilam muito (marcação a mercado).","r":"Matemática financeira"},{"id":"b21","t":"b3","q":"A duration de um título sem cupom (zero cupom) é:","o":["Igual ao prazo até o vencimento","Sempre zero","A metade do prazo","Maior que o prazo"],"c":0,"e":"Para títulos com cupom, a duration é menor que o prazo, pois parte do fluxo é recebida antes.","r":"Fortuna; Assaf"},{"id":"b22","t":"b3","q":"Quanto maior a duration de um título:","o":["Maior a sensibilidade do seu preço a mudanças na taxa de juros","Menor o risco de taxa","Maior o cupom pago","Menor o prazo"],"c":0,"e":"A duration modificada mede a variação percentual aproximada do preço para cada ponto de variação da taxa.","r":"Fortuna; Assaf"},{"id":"b23","t":"b3","q":"Pela tabela regressiva do IR em renda fixa, uma aplicação resgatada após 400 dias paga alíquota de:","o":["17,5%","22,5%","20%","15%"],"c":0,"e":"Até 180 dias 22,5%; de 181 a 360, 20%; de 361 a 720, 17,5%; acima de 720, 15%.","r":"Legislação do IR"},{"id":"b24","t":"b3","q":"Um CDB pós-fixado que paga 100% do CDI acompanha, aproximadamente:","o":["A taxa Selic","A inflação (IPCA)","O dólar","A poupança"],"c":0,"e":"O CDI anda colado na Selic over.","r":"Renda fixa"},{"id":"b25","t":"b3","q":"As debêntures são:","o":["Títulos de dívida emitidos por sociedades anônimas para captar recursos","Ações preferenciais","Títulos públicos federais","Contratos futuros de juros"],"c":0,"e":"O debenturista é credor, não sócio; as incentivadas (Lei 12.431) dão isenção de IR para pessoa física.","r":"Lei 6.404/1976"},{"id":"b26","t":"b3","q":"O \"spread de crédito\" de um título privado representa:","o":["O prêmio exigido acima do título público para compensar o risco do emissor","O IR cobrado na fonte","A comissão da corretora","A diferença entre compra e venda na bolsa"],"c":0,"e":"Emissores mais arriscados pagam spreads maiores.","r":"Renda fixa"},{"id":"b27","t":"b3","q":"Um título que paga IPCA + 6% ao ano protege o investidor principalmente contra:","o":["A inflação","A alta do dólar","A queda da bolsa","O risco de crédito do emissor"],"c":0,"e":"O juro real fica garantido se carregado até o vencimento.","r":"Renda fixa"},{"id":"b28","t":"b4","q":"No mercado futuro, o ajuste diário significa que:","o":["Os ganhos e perdas são liquidados todo dia com base no preço de ajuste","O contrato só é liquidado no vencimento","O preço é fixo até o vencimento","Não há necessidade de margem"],"c":0,"e":"Diferente do termo, que liquida só no vencimento.","r":"B3"},{"id":"b29","t":"b4","q":"A margem de garantia nos mercados futuros serve para:","o":["Cobrir o risco de inadimplência dos participantes","Pagar o prêmio da opção","Remunerar a corretora","Distribuir dividendos"],"c":0,"e":"A câmara de compensação exige margem para garantir as posições.","r":"B3"},{"id":"b30","t":"b4","q":"O titular de uma opção de compra (call):","o":["Tem o direito, mas não a obrigação, de comprar o ativo pelo preço de exercício","Tem a obrigação de comprar o ativo","Tem a obrigação de vender o ativo","Recebe o prêmio"],"c":0,"e":"Quem paga o prêmio é o titular; quem recebe e assume a obrigação é o lançador.","r":"Derivativos"},{"id":"b31","t":"b4","q":"O lançador (vendedor) de uma opção de venda (put) tem:","o":["A obrigação de comprar o ativo pelo preço de exercício, se exercido","O direito de vender o ativo","A obrigação de vender o ativo","O direito de comprar o ativo"],"c":0,"e":"Ele recebe o prêmio e assume a obrigação.","r":"Derivativos"},{"id":"b32","t":"b4","q":"Uma opção de estilo europeu pode ser exercida:","o":["Somente na data de vencimento","A qualquer momento até o vencimento","Somente antes do vencimento","Apenas pelo lançador"],"c":0,"e":"A de estilo americano pode ser exercida a qualquer momento até o vencimento.","r":"Derivativos"},{"id":"b33","t":"b4","q":"Uma call está \"dentro do dinheiro\" (ITM) quando:","o":["O preço do ativo está acima do preço de exercício","O preço do ativo está abaixo do preço de exercício","O preço do ativo é igual ao de exercício","O prêmio é zero"],"c":0,"e":"Para a put é o contrário: ITM quando o ativo está abaixo do strike.","r":"Derivativos"},{"id":"b34","t":"b4","q":"O valor de uma opção é formado por:","o":["Valor intrínseco mais valor extrínseco (valor do tempo)","Somente valor intrínseco","Somente volatilidade","O preço do ativo mais o strike"],"c":0,"e":"O valor extrínseco depende de tempo, volatilidade e juros e vai a zero no vencimento.","r":"Black & Scholes"},{"id":"b35","t":"b4","q":"Um produtor de soja que teme a queda do preço até a colheita faz hedge:","o":["Vendendo contratos futuros de soja","Comprando contratos futuros de soja","Comprando calls de soja","Não há como se proteger"],"c":0,"e":"Venda futura trava o preço de venda; um comprador de soja (indústria) faria hedge comprado.","r":"Derivativos"},{"id":"b36","t":"b4","q":"O swap é um derivativo em que:","o":["As partes trocam fluxos de rentabilidade (ex.: taxa prefixada por CDI) sobre um valor de referência","Uma parte compra uma opção da outra","Há ajuste diário em bolsa obrigatório","As partes trocam ações ON por PN"],"c":0,"e":"É negociado no balcão e liquidado pela diferença.","r":"Derivativos"},{"id":"b37","t":"b4","q":"No contrato a termo, diferentemente do futuro:","o":["A liquidação ocorre só no vencimento, sem ajuste diário, e o contrato não é padronizado da mesma forma","Há ajuste diário","Não há prazo definido","Só pessoas jurídicas podem negociar"],"c":0,"e":"Por isso o termo tem maior risco de contraparte.","r":"Derivativos"},{"id":"b38","t":"b4","q":"A volatilidade implícita de uma opção é:","o":["A volatilidade que, colocada no modelo de precificação, iguala o preço teórico ao preço de mercado","A volatilidade histórica dos últimos 21 dias","O desvio padrão do volume","O prêmio dividido pelo strike"],"c":0,"e":"Representa a expectativa do mercado sobre a oscilação futura.","r":"Black & Scholes"},{"id":"b39","t":"b5","q":"Pela ótica da despesa, o PIB é igual a:","o":["Consumo + Investimento + Gastos do governo + (Exportações − Importações)","Salários + Lucros","Consumo − Impostos","Exportações + Importações"],"c":0,"e":"Y = C + I + G + (X − M).","r":"Macroeconomia"},{"id":"b40","t":"b5","q":"O índice oficial de inflação usado no sistema de metas brasileiro é o:","o":["IPCA, calculado pelo IBGE","IGP-M, da FGV","INPC","IPC-Fipe"],"c":0,"e":"O IGP-M é usado em contratos de aluguel e tarifas.","r":"Sistema de metas"},{"id":"b41","t":"b5","q":"Uma política monetária contracionista envolve, por exemplo:","o":["Elevar a taxa básica de juros","Aumentar os gastos do governo","Reduzir os impostos","Reduzir o depósito compulsório"],"c":0,"e":"Juros mais altos encarecem o crédito e reduzem a demanda, combatendo a inflação.","r":"Política monetária"},{"id":"b42","t":"b5","q":"Uma política fiscal expansionista consiste em:","o":["Aumentar gastos públicos ou reduzir impostos","Aumentar a taxa Selic","Vender títulos para enxugar liquidez","Aumentar o compulsório"],"c":0,"e":"A política fiscal é conduzida pelo governo (Tesouro), não pelo Banco Central.","r":"Política fiscal"},{"id":"b43","t":"b5","q":"Pela relação de Fisher, se a taxa nominal é de 12% e a inflação é de 5%, o juro real é de aproximadamente:","o":["6,67%","7%","17%","2,4%"],"c":0,"e":"(1,12 / 1,05) − 1 = 6,67%. A conta simples (12 − 5) é só uma aproximação.","r":"Matemática financeira"},{"id":"b44","t":"b5","q":"Uma desvalorização do real frente ao dólar tende a:","o":["Favorecer as exportações e encarecer as importações","Reduzir a inflação imediatamente","Prejudicar todas as empresas exportadoras","Não ter efeito na balança comercial"],"c":0,"e":"Também pressiona a inflação pelo preço dos importados.","r":"Macroeconomia"},{"id":"b45","t":"b5","q":"O balanço de pagamentos registra:","o":["Todas as transações econômicas entre residentes e não residentes do país","Apenas o orçamento do governo","A dívida interna","Somente as exportações"],"c":0,"e":"Divide-se em transações correntes, conta capital e conta financeira.","r":"Macroeconomia"},{"id":"b46","t":"b5","q":"O resultado primário do governo é:","o":["Receitas menos despesas, excluindo o pagamento de juros da dívida","Receitas menos todas as despesas, incluindo juros","O PIB dividido pela dívida","O saldo da balança comercial"],"c":0,"e":"O resultado nominal inclui os juros.","r":"Finanças públicas"},{"id":"b47","t":"b5","q":"Quando a inflação está acima da meta e as expectativas sobem, a reação esperada do Banco Central é:","o":["Elevar ou manter elevada a Selic","Cortar a Selic","Imprimir mais moeda","Desvalorizar o câmbio"],"c":0,"e":"O sistema de metas usa o juro para ancorar expectativas.","r":"Política monetária"},{"id":"b48","t":"b6","q":"A atividade de analista de valores mobiliários no Brasil é regulada principalmente pela:","o":["Resolução CVM 20/2021","Lei 4.595/1964","Resolução do CMN sobre crédito rural","Lei de Falências"],"c":0,"e":"A Resolução CVM 20 trata do credenciamento e da conduta do analista; a Apimec é entidade credenciadora.","r":"Resolução CVM 20"},{"id":"b49","t":"b6","q":"Nos relatórios de análise, o analista deve:","o":["Divulgar eventuais conflitos de interesse, como participação no ativo analisado","Omitir qualquer informação sobre sua remuneração","Garantir rentabilidade ao investidor","Divulgar apenas recomendações de compra"],"c":0,"e":"Transparência sobre conflitos é exigência regulatória e ética.","r":"Resolução CVM 20"},{"id":"b50","t":"b6","q":"Usar informação relevante ainda não divulgada ao mercado para negociar valores mobiliários configura:","o":["Uso indevido de informação privilegiada (insider trading), que é crime","Prática permitida se o lucro for pequeno","Arbitragem","Hedge"],"c":0,"e":"Tipificado na Lei 6.385/1976.","r":"Lei 6.385/1976"},{"id":"b51","t":"b6","q":"Ato ou fato que possa influir de modo ponderável na cotação dos valores mobiliários da companhia deve ser divulgado como:","o":["Fato relevante","Comunicado interno","Ata de reunião de diretoria apenas","Release de marketing"],"c":0,"e":"A divulgação de fato relevante é regulada pela Resolução CVM 44.","r":"Resolução CVM 44"},{"id":"b52","t":"b6","q":"A prática de criar condições artificiais de demanda ou de preço (ex.: negociar entre contas ligadas para inflar o volume) é chamada de:","o":["Manipulação de mercado","Hedge","Arbitragem","Day trade"],"c":0,"e":"É ilícito previsto na regulamentação e na Lei 6.385.","r":"Lei 6.385/1976"},{"id":"b53","t":"b6","q":"Um analista que recomenda compra de uma ação e, ao mesmo tempo, vende essa ação na conta própria, sem informar, viola principalmente o dever de:","o":["Lealdade e transparência com o cliente","Sigilo bancário","Diligência contábil","Pontualidade"],"c":0,"e":"O interesse do cliente deve prevalecer e os conflitos devem ser informados.","r":"Código de Conduta Apimec"},{"id":"b54","t":"b6","q":"O \"front running\" é:","o":["Negociar à frente de ordens de clientes conhecidas, para se beneficiar delas","Comprar ações na abertura do pregão","Operar apenas a favor da tendência","Fazer hedge de uma carteira"],"c":0,"e":"É prática vedada.","r":"Conduta"},{"id":"b55","t":"b7","q":"No segmento Novo Mercado da B3, a empresa:","o":["Só pode ter ações ordinárias","Pode emitir ações preferenciais sem limite","Não precisa ter conselho de administração","Não precisa divulgar demonstrações em inglês nem ter regras extras"],"c":0,"e":"O Novo Mercado também exige tag along de 100% e conselheiros independentes.","r":"Regulamento do Novo Mercado"},{"id":"b56","t":"b7","q":"Os membros do conselho de administração de uma S.A. são eleitos:","o":["Pela assembleia geral de acionistas","Pela diretoria","Pela CVM","Pelos funcionários, exclusivamente"],"c":0,"e":"O conselho, por sua vez, elege e destitui os diretores.","r":"Lei 6.404/1976"},{"id":"b57","t":"b7","q":"O conselho fiscal tem como função principal:","o":["Fiscalizar os atos dos administradores e opinar sobre as demonstrações financeiras","Definir a estratégia de marketing","Eleger o presidente da República","Negociar ações em bolsa em nome da empresa"],"c":0,"e":"É órgão de fiscalização, independente da administração.","r":"Lei 6.404/1976"},{"id":"b58","t":"b7","q":"A área de Relações com Investidores (RI) é responsável por:","o":["Comunicar-se com acionistas, analistas e o mercado, e divulgar informações da companhia","Definir a taxa de juros da empresa","Auditar as contas da companhia","Negociar as ações da tesouraria no mercado"],"c":0,"e":"O diretor de RI responde pela divulgação de informações à CVM e ao mercado.","r":"Resolução CVM 80"},{"id":"b59","t":"b7","q":"A sigla ESG refere-se a critérios:","o":["Ambientais, sociais e de governança","Econômicos, de solvência e de garantia","De emissão, subscrição e garantia firme","De estoques, serviços e ganhos"],"c":0,"e":"Usados para avaliar sustentabilidade e riscos não financeiros.","r":"Sustentabilidade"},{"id":"b60","t":"b7","q":"Um dos princípios básicos de governança corporativa (IBGC) é:","o":["Transparência, equidade, prestação de contas e responsabilidade corporativa","Sigilo absoluto sobre resultados","Concentração das decisões no controlador","Remuneração variável sem limites"],"c":0,"e":"São os quatro princípios do Código de Melhores Práticas do IBGC.","r":"IBGC"},{"id":"b61","t":"b7","q":"Conselheiro independente é aquele que:","o":["Não tem vínculo relevante com a companhia, o controlador ou a administração","É funcionário da empresa","É parente do controlador","É indicado pelo diretor-presidente"],"c":0,"e":"Ajuda a proteger os interesses de todos os acionistas.","r":"IBGC; Novo Mercado"}]};
